// Build the morning report message for the manager.
// Inputs: night_queue leads + night conversation stats.

const queueItems = $('Fetch Pending Night Queue').all().map(i => i.json);
const stats = $('Fetch Night Stats').first().json;

const totalQueued = queueItems.length;
const totalConvs = parseInt(stats.total_night_conversations || 0);
const fromInmuebles = parseInt(stats.from_inmuebles24 || 0);
const fromEasyBroker = parseInt(stats.from_easybroker || 0);
const fromWhatsApp = parseInt(stats.from_whatsapp_direct || 0);

// Build header
const lines = [];
lines.push('===========================');
lines.push('REPORTE MATUTINO');
lines.push(new Date().toLocaleDateString('es-MX', { timeZone: 'America/Mexico_City', weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' }));
lines.push('===========================');
lines.push('');

// Night stats summary
lines.push(`Conversaciones nocturnas: ${totalConvs}`);
lines.push(`Leads en cola pendiente: ${totalQueued}`);
lines.push('');

if (totalConvs > 0 || totalQueued > 0) {
  lines.push('--- Desglose por fuente ---');
  if (fromInmuebles > 0) lines.push(`  Inmuebles24: ${fromInmuebles}`);
  if (fromEasyBroker > 0) lines.push(`  EasyBroker: ${fromEasyBroker}`);
  if (fromWhatsApp > 0) lines.push(`  WhatsApp directo: ${fromWhatsApp}`);
  lines.push('');
}

// Detail each queued lead
if (totalQueued > 0) {
  lines.push('--- Leads en cola ---');
  lines.push('');
  queueItems.forEach((lead, idx) => {
    lines.push(`${idx + 1}. ${lead.lead_name || 'Sin nombre'}`);
    lines.push(`   Tel: ${lead.lead_phone}`);
    if (lead.property_id) lines.push(`   Propiedad: ${lead.property_id}`);
    if (lead.temperature) lines.push(`   Temperatura: ${lead.temperature.toUpperCase()}`);
    if (lead.source) lines.push(`   Fuente: ${lead.source}`);
    if (lead.bot_summary) {
      lines.push(`   Resumen bot: ${lead.bot_summary}`);
    }
    lines.push('');
  });
} else {
  lines.push('No hay leads pendientes en la cola nocturna.');
  lines.push('');
}

lines.push('El proceso TOMO automatico se ejecutara a las 8:05 AM.');

const reportText = lines.join('\n');

return [{
  json: {
    report_text: reportText,
    total_queued: totalQueued,
    total_conversations: totalConvs
  }
}];

// Store total count before splitting into batches.
const items = $input.all();
return items.map(item => ({
  json: {
    ...item.json,
    _total_queue_count: items.length
  }
}));

// Count durable queue activations returned by drain_night_queue().
const allItems = $('Fetch Queue for Processing').all();
const total = allItems.length;

return [{
  json: {
    total_processed: total,
    message: `Se activaron ${total} leads de la cola nocturna para routing.`
  }
}];

